'use client'

import { useActionState } from 'react'
import { useFormStatus } from 'react-dom'

async function submitContact(prevState: { success?: string; error?: string } | null, formData: FormData) {
  'use server'

  const name = formData.get('name') as string
  const email = formData.get('email') as string
  const message = formData.get('message') as string

  if (!name || !name.trim()) {
    return { error: 'Name is required.' }
  }

  if (!email || !email.trim()) {
    return { error: 'Email is required.' }
  }

  if (!message || !message.trim()) {
    return { error: 'Message is required.' }
  }

  console.log('Contact form submission:', { name: name.trim(), email: email.trim(), message: message.trim() })

  return { success: 'Thank you for your message! We will get back to you soon.' }
}

function SubmitButton() {
  const { pending } = useFormStatus()

  return (
    <button type="submit" disabled={pending}>
      {pending ? 'Sending...' : 'Send Message'}
    </button>
  )
}

export default function ContactForm() {
  const [state, formAction] = useActionState(submitContact, null)

  return (
    <div>
      <h2>Contact Us</h2>

      {state?.success && <p style={{ color: 'green' }}>{state.success}</p>}
      {state?.error && <p style={{ color: 'red' }}>{state.error}</p>}

      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Your name" required />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" placeholder="Your email" required />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" placeholder="Your message" required />
        </div>
        <SubmitButton />
      </form>
    </div>
  )
}
